1794	          `缺少必填参数: ${missing.map((m) => `--${m}`).join(', ')}`,
1795	        );
1796	      }
1797	      const r = await policySign({
1798	        policy: args.policy,
1799	        key: args.key,
1800	        signature: args.signature,
1801	      });
1802	      process.stdout.write(
1803	        `${stableJsonStringify({
1804	          status: 'POLICY_SIGNED',
1805	          policyPath: r.policyPath,
1806	          signaturePath: r.signaturePath,
1807	          policySignerFingerprint: r.policySignerFingerprint,
1808	        })}\n`,
1809	      );
1810	      return 0;
1811	    }
1812	
1813	    if (command === 'verify') {
1814	      // 包模式：--bundle 与独立文件入口（--proof/--signature/--sbom/
1815	      // --sbom-signature/--cosignatures）互斥，混用为 USAGE_ERROR。
1816	      const bundleMode = args.bundle !== undefined;
1817	      if (bundleMode && typeof args.bundle !== 'string') {
1818	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '--bundle 需要提供证明分发包路径');
1819	      }
1820	      if (bundleMode) {
1821	        const conflicts = ['proof', 'signature', 'sbom', 'sbom-signature', 'cosignatures'].filter(
1822	          (k) => args[k] !== undefined,
1823	        );
1824	        if (conflicts.length) {
1825	          throw new ProvError(
1826	            ERROR_CODES.USAGE_ERROR,
1827	            `--bundle 与 ${conflicts.map((k) => `--${k}`).join('、')} 互斥`,
1828	          );
1829	        }
1830	      }
1831	      const required = bundleMode ? ['artifact', 'key'] : ['artifact', 'proof', 'signature', 'key'];
1832	      const missing = required.filter((k) => typeof args[k] !== 'string');
1833	      if (missing.length) {
1834	        throw new ProvError(
1835	          ERROR_CODES.USAGE_ERROR,
1836	          `缺少必填参数: ${missing.map((m) => `--${m}`).join(', ')}`,
1837	        );
1838	      }
1839	      // --policy 为可选单值参数；出现时必须带文件路径。
1840	      const hasPolicy = args.policy !== undefined;
1841	      if (hasPolicy && typeof args.policy !== 'string') {
1842	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '--policy 需要提供策略文件路径');
1843	      }
1844	      // --policy-signature 与 --policy-key 必须成对出现，且必须与 --policy 同时提供；
1845	      // 缺值（后无路径）或只给一者均为 USAGE_ERROR。
1846	      const polSigRaw = args['policy-signature'];
