1849	      if (anyPolicySign || hasPolicy) {
1850	        if (anyPolicySign && !hasPolicy) {
1851	          throw new ProvError(
1852	            ERROR_CODES.USAGE_ERROR,
1853	            '--policy-signature 与 --policy-key 必须与 --policy 同时提供',
1854	          );
1855	        }
1856	      }
1857	      if (anyPolicySign && (typeof polSigRaw !== 'string' || typeof polKeyRaw !== 'string')) {
1858	        throw new ProvError(
1859	          ERROR_CODES.USAGE_ERROR,
1860	          '--policy-signature 与 --policy-key 必须同时提供且都需要文件路径',
1861	        );
1862	      }
1863	      // --sbom 与 --sbom-signature 必须成对出现（仅独立文件模式；包模式自带 SBOM 成员）。
1864	      const hasSbom = typeof args.sbom === 'string';
1865	      const hasSbomSig = typeof args['sbom-signature'] === 'string';
1866	      if (!bundleMode && hasSbom !== hasSbomSig) {
1867	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '--sbom 与 --sbom-signature 必须成对提供');
1868	      }
1869	      // 共签校验：独立文件模式需 --cosignatures + --cosigner-key（可重复）+ --min-cosigners；
1870	      // 包模式清单位于包内，只需 --cosigner-key + --min-cosigners。min 为不超过公钥数量的正整数。
1871	      const cosigKeysRaw = args['cosigner-key'];
