1873	        args.cosignatures !== undefined || cosigKeysRaw !== undefined || args['min-cosigners'] !== undefined;
1874	      let cosignOpts = {};
1875	      if (anyCosign) {
1876	        const keyListOk =
1877	          Array.isArray(cosigKeysRaw) &&
1878	          cosigKeysRaw.length > 0 &&
1879	          cosigKeysRaw.every((k) => typeof k === 'string');
1880	        const minRaw = args['min-cosigners'];
1881	        const minOk =
