1883	        const dirOk = bundleMode || typeof args.cosignatures === 'string';
1884	        if (!dirOk || !keyListOk || !minOk) {
1885	          throw new ProvError(
1886	            ERROR_CODES.USAGE_ERROR,
1887	            bundleMode
1888	              ? '--cosigner-key（可重复）与 --min-cosigners（正整数）必须同时提供'
1889	              : '--cosignatures、--cosigner-key（可重复）与 --min-cosigners（正整数）必须同时提供',
1890	          );
1891	        }
