1920	      });
1921	      process.stdout.write(`${stableJsonStringify(r)}\n`);
1922	      return 0;
1923	    }
1924	
1925	    throw new ProvError(ERROR_CODES.USAGE_ERROR, `未知子命令: ${command}`);
1926	  } catch (err) {
