1	// Prov Guard 端到端测试：以子进程方式驱动 provguard.mjs CLI。
2	// 运行：node --test
3	import { spawnSync } from 'node:child_process';
4	import { sign as cryptoSign, createPrivateKey, createPublicKey, createHash, generateKeyPairSync } from 'node:crypto';
5	import { mkdtempSync, mkdirSync, readFileSync, rmSync, writeFileSync, chmodSync, symlinkSync, existsSync } from 'node:fs';
6	import { tmpdir } from 'node:os';
7	import { join } from 'node:path';
8	import { fileURLToPath } from 'node:url';
9	import { test, beforeEach, afterEach } from 'node:test';
10	import assert from 'node:assert/strict';
11	import { stableJsonStringify } from '../provguard.mjs';
12	
13	const CLI = fileURLToPath(new URL('../provguard.mjs', import.meta.url));
14	
15	let root;
16	let paths;
17	
18	function makeTree() {
19	  const art = join(root, 'art');
20	  mkdirSync(join(art, 'sub', 'deep'), { recursive: true });
21	  mkdirSync(join(art, 'emptydir'));
22	  writeFileSync(join(art, 'a.txt'), 'hello world\n');
23	  writeFileSync(join(art, 'empty.bin'), Buffer.alloc(0));
24	  writeFileSync(join(art, 'sub', 'b.txt'), 'nested\n');
25	  writeFileSync(join(art, 'sub', 'deep', 'c.bin'), Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0, 0]));
26	  return art;
27	}
28	
29	beforeEach(() => {
30	  root = mkdtempSync(join(tmpdir(), 'provguard-test-'));
31	  const art = makeTree();
32	  paths = { art, keys: join(root, 'keys'), out: join(root, 'attest'), keys2: join(root, 'keys2') };
33	});
34	
35	afterEach(() => {
36	  // 测试可能 chmod 000，先恢复再删除。
37	  chmodSafe(join(paths.out, 'proof.json'));
38	  rmSync(root, { recursive: true, force: true });
39	});
40	
41	function chmodSafe(p) {
42	  try {
43	    chmodSync(p, 0o644);
44	  } catch {
45	    /* ignore */
46	  }
47	}
48	
