});

test('bundle 模式：1.1 策略（含签名）往返', () => {
  const k = keygen(paths.keys);
  const g = generateBundle(paths.art, k.priv, paths.out);
  const proof = readProof();
  const p = writePolicy(
    {
      policyVersion: '1.1',
      requireSbom: true,
      requiredFiles: {
        'a.txt': fileDigest(proof, 'a.txt'),
        'sub/b.txt': fileDigest(proof, 'sub/b.txt'),
      },
